if($b['status']!=='Review'){echo '<div class="alert info">'.e($b['status']==='Posted'?'This return is posted.':'This return is '.$b['status'].'.').'</div>';$editable=false;}
else echo '<div class="alert info">No inventory added yet. Good items return to their original platform; damaged and For Repackaging items go to their separate restricted views.</div>';
