echo '<div class="card table-wrap"><h3>'.($final?'Final Return Summary':'Uploaded Items & Corrections').'</h3><table class="table"><tr><th>Order ID / Date</th><th>Product</th><th>Platform</th><th>Original</th><th>Previously Returned</th><th>Return Qty / Condition</th><th>Remaining After</th><th>Review / Remarks</th></tr>';
