'</table></div>';
if($editable){echo '<div class="card modal-actions">';if($final)echo '<a class="btn secondary" href="?page=order_return&id='.$id.'">Back to Review</a><form method="post" action="actions.php" class="stack" data-confirm="Post this return? Good items restore their original platform and damaged and For Repackaging items go to their separate restricted views."><input type="hidden" name="action" value="return_confirm"><input type="hidden" name="batch_id" value="'.$id.'"><input type="hidden" name="digest" value="'.$a['digest'].'"><input type="hidden" name="return" value="order_return&id='.$id.'"><label class="ack"><input type="checkbox" name="review_ack" value="1" required> I checked the physical return, original order and condition quantities. Any similar prior return is a separate physical return explained in Remarks.</label><button class="btn primary" '.(!$canConfirm?'disabled':'').'>'.($damageOnly?'Validate &amp; Post Return':'Confirm Return').'</button></form>';elseif(!$a['errors'])echo '<a class="btn primary" href="?page=order_return&id='.$id.'&step=confirm">'.($damageOnly?'Review &amp; Validate Return':'Submit for Final Confirmation').'</a>';echo '<form method="post" action="actions.php" data-confirm="Cancel this return upload? No stock will be added."><input type="hidden" name="action" value="return_cancel"><input type="hidden" name="batch_id" value="'.$id.'"><input type="hidden" name="return" value="order_return&id='.$id.'"><button class="btn ghost">Cancel Upload</button></form></div>';}
